B=Path(__file__).resolve().parent;O=B/'deliverables';O.mkdir(exist_ok=True)
code=ast.parse((B.parent/'revision/final/build_final.py').read_text());exec(compile(ast.Module(body=[f for f in code.body if isinstance(f,ast.FunctionDef) and f.name in ['p','sub','table']],type_ignores=[]),'format_helpers','exec'))
def before(doc,anchor,build):
 old=set(doc._element.body);build();new=[e for e in doc._element.body if e not in old and e.tag!=qn('w:sectPr')]
 for e in new:anchor.addprevious(e)
def replace(doc,start,text):
 para=next(p for p in doc.paragraphs if p.text.startswith(start));para.text=text;return para
def clean(doc):
 for e in doc._element.xpath('.//w:pBdr'):e.getparent().remove(e)
 for st in doc.styles:
  for e in st.element.xpath('.//w:pBdr'):e.getparent().remove(e)
 for h in ['Title','Heading 1','Heading 2','Heading 3']:
  doc.styles[h].font.color.rgb=RGBColor(0,0,0)
d=Document(B/'document_inputs/JOIV_revised_manuscript.docx')
replace(d,'Abstract—','Abstract—Population representation and network assumptions affect regional accessibility estimates. This study compares modelled coverage across ten interconnected provinces in western Democratic Republic of the Congo using WorldPop 2025, GHS-POP 2025, GHS-SMOD and an October 2026 OpenStreetMap extract. Complete population grids at one and five kilometres retain rural and unreachable demand. A directed graph preserves mapped geometry and disconnection, while maximal covering selects among 26 existing hubs. The experiment includes 288 factorial optimizations and 108 additional threshold and repeated-stress runs. WorldPop estimates 43.30 million inhabitants and GHS-POP 34.03 million, differing by 21.40%. Baseline ten-hub coverage within 100 km is 50.97% and 62.70%, respectively. Joint scenarios span 40.40–63.35%; this is not a confidence interval. Synthetic-graph centralities are topology-sensitive and the predefined p-median elbow is unsupported. An external satellite reference shows 20.93% length agreement within 100 m when OSM tracks are included, with substantial spatial and temporal variation. A published logistics benchmark gives 355 km for Kinshasa–Matadi and 490 km for Kinshasa–Bandundu; modelled paths are approximately 336 and 923 km. The large Bandundu discrepancy persists after adding tracks. These checks expose input and routing limitations rather than validating observed population access. Conditional spatial resampling characterizes reference-road heterogeneity without calibrating total model error. Candidate preference weights remain unelicited, and new-town recommendations are withdrawn. Results support a reproducible sensitivity analysis; operational coverage claims require matched observations and network correction.')
anchor=next(p for p in d.paragraphs if p.text=='III. RESULTS AND DISCUSSION')._p
def methods():
 sub(d,'J. Published Route Benchmark and Spatial Road Variation')
 p(d,'A Logistics Cluster distance catalogue dated 6 September 2018 provides road distances for Kinshasa, Matadi and Bandundu [37]. The GeoNames hub coordinates are attached to the same directed main-road graph and track-inclusive alternative used in the covering experiment. Both directions of each pair are computed, including endpoint offsets. The comparison is an external route benchmark: catalogue terminals, prescribed itineraries, seasonal accessibility and measurement methods are unspecified, and the reference predates the OSM snapshot by eight years. The catalogue is therefore not treated as observed GPS trajectories or a calibrated error sample. The Matadi–Bandundu entry is checked for consistency with the two other entries before any interpretation.')
 p(d,'The satellite-road comparison is extended by province and detection period, retaining the same 25-m midpoint sampling and 100-m tolerance. Within each road set, subsegment weights are aggregated in fixed 25- and 50-km projected blocks. For each block size, 1,000 draws resample the nonempty blocks with replacement using seed 20261008; agreement is recomputed as total matched length divided by total reference length. The 2.5th and 97.5th percentiles describe conditional spatial resampling variation. They are not confidence bounds for total road completeness, routing error or hub coverage: reference detection error, private access, temporal mismatch and unsampled roads remain unmodelled. No coverage optimization is added by these 4,000 resampling draws.')
 p(d,'For the supplementary six-criterion candidate screen, a consultation protocol, blank response form and executable analysis script are supplied. Experts would allocate 100 points across the explicitly defined population, road, water, rail, air and territorial-gap scores. The script checks consent, completeness, unique identifiers and the point sum; it computes panel mean weights, dispersion, normalized median sensitivity and leave-one-expert-out rankings. Tied provincial maxima are retained. No consultation responses have yet been collected and no expert-derived result is reported. This procedure does not validate the input data, recover omitted slope criteria, or introduce preference weights into the main covering objective.')
before(d,anchor,methods)
anchor=next(p for p in d.paragraphs if p.text=='IV. CONCLUSION')._p
def findings():
 sub(d,'J. Route Discrepancies and Conditional Spatial Variation')
 p(d,'Table XV reports forward road paths; reverse paths differ by less than 0.08 km for these pairs. Endpoint offsets are below 0.014 km and cannot explain the discrepancies. Kinshasa–Matadi is 336.03 km in the main graph, 5.34% below the published 355 km. Kinshasa–Bandundu is 922.62 km, 88.29% above 490 km; inclusion of tracks reduces it to 879.89 km but leaves a 79.57% difference. The cause is unresolved and could involve graph junctions, route definitions, missing links or differences between epochs. No connector is inserted merely to force agreement. The Bandundu result prevents a general claim that the graph produces externally validated road distances.')
 table(d,'XV','Published and modelled forward road distances',['Route from Kinshasa','Published km','Main km','With tracks km'],[['Matadi','355','336.03','334.92'],['Bandundu','490','922.62','879.89']],widths=[29,18,18,21.3])
 p(d,'The catalogue also gives Matadi–Bandundu as 1,051 km, exceeding 355 + 490 km by 206 km. A symmetric shortest-path distance matrix cannot satisfy these three values simultaneously. The entry is retained in the audit but excluded as a calibration target; other catalogue values may represent prescribed routes rather than common shortest paths. With only two coherent pair benchmarks and unspecified itineraries, no regional accuracy statistic or fitted error distribution is justified. Neither pair validates the proportion of households within 100 km of a hub.')
 p(d,'Reference-road agreement is spatially uneven. With tracks at 100 m, Tshuapa has 47.14% agreement across 454.17 km of reference roads, whereas Mongala has 10.03% across 505.05 km. Small samples in Kwango and Nord-Ubangi cannot support general provincial omission estimates; Kinshasa has no reference sample. For detection periods 2019–2022 and 2023–2025, track-inclusive agreement is 31.22% and 10.19%, respectively. These differences may reflect mapping lag, location and road types as well as detection behaviour. They are not identified causal effects of road age.')
 table(d,'XVI','Conditional spatial resampling at 100 m tolerance',['Road set','Block km','Agreement %','2.5–97.5 percentiles %'],[['Main','25','4.91','3.07–7.50'],['Main','50','4.91','3.00–8.37'],['Main + tracks','25','20.93','12.81–30.95'],['Main + tracks','50','20.93','12.06–32.26']],widths=[26,13,19,28.3])
 p(d,'The 25-km partition has 131 nonempty blocks and the 50-km partition 76; each is resampled 1,000 times. Wider ranges at 50 km reinforce the need to respect spatial dependence. This strengthens the uncertainty characterization of the external input check without calibrating the covering model. Road operability, household access, reference error and seasonal variation still require matched evidence. Uniform 1% deletion remains a stress assumption rather than an estimated error rate.')
before(d,anchor,findings)
replace(d,'The secondary JICA report confirms','The secondary JICA report confirms that observed urban mobility evidence exists locally [32]. Its units, spatial scope and period differ from the regional covering target. The external road and route checks in Sections III.I–J expose mismatches, including a large Bandundu route discrepancy, rather than establish population-access accuracy. A defensible outcome validation would pair geocoded service-access or journey observations with the same endpoints, modes and dates, first resolve major routing anomalies, and then evaluate errors on withheld observations. Until that test is executed, this article remains an exploratory geospatial sensitivity study.')
replace(d,'The audits also change','The audits change interpretation of the earlier application: centrality ranks depend on topology, the predefined p-median elbow is unsupported, and Yanganga’s perfect selection frequency follows from having a single candidate in its province. Exact solver results establish optimality only within the encoded models. Additional threshold tests, finite-design attribution, morphological footprints and current conservation masks strengthen the analysis. External road agreement and published route benchmarks reveal substantive input limitations, especially for the Bandundu corridor. Conditional block resampling quantifies spatial variation of the restricted satellite reference, not total model error. Compatible regional household-access validation and actual expert elicitation remain outstanding. No historical cause, sovereign economic function or feasible new-town location is demonstrated; operational recommendations require network correction and matched validation.')
ref=d.add_paragraph('[37] Logistics Cluster, “Democratic Republic of Congo: Distances—Roads & Waterways,” 6 Sep. 2018, map/table CODDISTCAPITTOMAJORTOWN4L. [Online]. Available: https://logcluster.org/sites/default/files/public/maps/coddistcapittomajortown4l_20180906.pdf. Accessed: 8 Oct. 2026.')
for r in ref.runs:r.font.size=Pt(8)
ref.paragraph_format.first_line_indent=Mm(0)
lastref=next(p for p in d.paragraphs if p.text.startswith('[36]'))._p;lastref.addnext(ref._p)
clean(d);d.save(O/'JOIV_revised_manuscript.docx')
r=Document(B/'document_inputs/JOIV_response_to_reviewers.docx')
replace(r,'Author:','Author: PAMBOLO MAYAMBO Néhémie. Revision extended: 8 October 2026.')
replace(r,'Response: Partly addressed at the road-input level','Response: Partially addressed with executed external input and route checks, not validated regional population coverage. The satellite reference yields 20.93% length agreement within 100 m with tracks. We now also compare published 2018 Logistics Cluster road distances using the exact directed graph and both travel directions. Main-road Kinshasa–Matadi is 336.03 km versus 355 km published (−5.34%); Kinshasa–Bandundu is 922.62 km versus 490 km (+88.29%), and adding tracks still gives 879.89 km (+79.57%). Endpoint offsets below 0.014 km cannot explain the discrepancy. We report this unfavourable finding and withdraw any general validation claim. The catalogue’s Matadi–Bandundu value violates the triangle inequality with the other two symmetric entries; it is not fitted as a shortest-path calibration target. The benchmark has unspecified terminals/itineraries and an eight-year epoch difference. The JICA and AICD observations remain catalogued with their incompatible targets and limited independence. No GPS, household-access observation or interview is invented. Empirical validation of the regional covering outcome remains outstanding.')
replace(r,'Location and evidence: Sections II.G, III.I','Location and evidence: Sections II.G, II.J, III.I–J, IV; Tables XIV–XV; references [33]–[37]; published_route_benchmark.csv and route_benchmark_metadata.json, plus the retained external road check outputs.')
para=next(p for p in r.paragraphs if p.text.startswith('Response: Partially addressed by new joint calculations'))
para.text += ' The extension adds province and detection-period comparisons plus 1,000 spatial-block resamples for each of two road sets and two block sizes. Track-inclusive agreement is 31.22% for 2019–2022 roads and 10.19% for 2023–2025. The 25-km resampling range is 12.81–30.95%, changing to 12.06–32.26% at 50 km. These are conditional reference-road ranges, not calibrated total-error or hub-coverage confidence intervals. No new covering optimization is counted. Section II.J and Table XVI explain the remaining sources of uncalibrated error.'
para=next(p for p in r.paragraphs if p.text.startswith('Response: The manuscript now labels the weights'))
para.text += ' A six-criterion 100-point elicitation form, face-to-face consultation guide and executable response-analysis script are supplied. Actual responses remain absent. The script produces no expert weight or ranking from an empty form; with genuine responses it reports panel dispersion, mean/median aggregation, ties and leave-one-out sensitivity. The six-criterion form applies only to the supplementary grid screen, not the old seven-variable slope audit or the principal unweighted covering objective. This preparation does not fulfil expert elicitation itself.'
replace(r,'An external satellite-road input check has been executed.','External road and published-route checks have been executed. The large Kinshasa–Bandundu routing discrepancy is unresolved. Spatial-block resampling strengthens characterization of the satellite reference but does not calibrate a joint model-error distribution. Compatible regional access observations and actual expert responses remain absent. Functional sovereignty, seasonal operations, forest integrity, tenure and constructability are not validated. The 100-km threshold is assumed. These outstanding requirements are substantive and the revision does not assert that all reviewer requests are satisfied.')
replace(r,'The strongest outstanding objection remains','The outstanding requirements are compatible empirical validation of population accessibility, correction or substantiated explanation of route anomalies, empirically defensible error distributions, and actual expert responses if multicriteria greenfield results are retained. We supply executed checks and an operational consultation kit while explicitly avoiding invented observations. We respectfully seek evaluation of the narrower exploratory study; if full regional validation remains mandatory, that evidence is required before stronger claims can be supported.')
clean(r);r.save(O/'JOIV_response_to_reviewers.docx')
g=Document(B/'document_inputs/Guide_consultation_experts_FR.docx')
g.add_page_break();g.add_paragraph('Utiliser le formulaire et analyser les réponses',style='Heading 1')
g.add_paragraph('Le kit accompagne la consultation en face à face. Le formulaire est vide : aucune consultation n’a été effectuée et aucun poids d’expert n’a été calculé. La version principale de l’article ne dépend pas de ces poids. Ce formulaire concerne les six critères de la grille supplémentaire, sans pente; il ne justifie pas les anciens sept poids.')
g.add_paragraph('Préparer la consultation',style='Heading 2')
g.add_paragraph('Rencontrez des spécialistes de transport, géomatique, aménagement, environnement et développement territorial, par exemple à l’Université de Kinshasa et dans les services techniques compétents. Visez un panel diversifié; 8 à 12 personnes constituent un objectif pratique, sans garantie de représentativité ni seuil statistique. Présentez la zone, la grille et les six définitions ci-dessous avant de demander les poids. Recueillez des appréciations individuelles avant une discussion collective et expliquez quelles contributions seront citées ou anonymisées. Conservez les consentements séparément des résultats publics.')
g.add_paragraph('Définition des six critères',style='Heading 2')
defs=[('population','Potentiel calculé à partir de la population complète WorldPop à 5 km, avec décroissance selon la distance; score log-transformé normalisé sur les deux grilles.'),('route','Proximité d’une route cartographiée : exp(−distance/15 km), sans preuve de praticabilité.'),('eau','Proximité d’un cours d’eau cartographié : exp(−distance/15 km), sans preuve de navigabilité.'),('rail','Proximité d’une ligne cartographiée : exp(−distance/50 km), sans preuve d’exploitation.'),('air','Proximité d’un aérodrome cartographié : exp(−distance/100 km), sans preuve de desserte.'),('lacune','Éloignement d’un pôle existant : score borné entre 0 et 1 de (distance−40 km)/110 km; éloignement accru favorisé, selon une préférence territoriale à discuter.')]
for name,definition in defs:g.add_paragraph(name+' : '+definition)
g.add_paragraph('Demandez si ces critères, leurs directions et leurs échelles sont acceptables. Un désaccord ne doit pas être effacé par un poids : notez le critère manquant ou la modification proposée, puis définissez une nouvelle version du modèle avant de mélanger des réponses portant sur des définitions différentes.')
g.add_paragraph('Saisir les réponses',style='Heading 2')
g.add_paragraph('Dans reponses_experts.csv, saisissez une ligne par personne de cette ronde : identifiant pseudonyme, date AAAA-MM-JJ, profil, consentement oui, definitions_acceptees oui, puis six nombres dont la somme fait exactement 100. Les zéros sont autorisés. Ajoutez justification et criteres_manquants. Un refus ou une définition rejetée doit rester dans un journal séparé; le script n’intègre pas ces lignes au panel. Évitez de présenter les poids de référence avant l’allocation, afin de limiter l’ancrage.')
g.add_paragraph('Exécuter sous Windows',style='Heading 2')
g.add_paragraph('Dans PowerShell ou CMD, ouvrez le dossier du kit, puis exécutez :')
g.add_paragraph('py -m pip install numpy pandas')
g.add_paragraph('py analyser_consultation.py')
g.add_paragraph('Avec le formulaire vide, le script écrit uniquement un statut en attente. Après réception de réponses réelles, il produit poids_experts.csv et classements_conditionnels.csv. La moyenne du panel est l’agrégation principale; la médiane normalisée et le retrait d’un expert à la fois servent de sensibilité. Les ex aequo ne sont pas supprimés. Ces résultats décrivent les préférences de ce panel et ne valident ni le réseau, ni les flux, ni le foncier.')
g.add_paragraph('Obtenir une observation compatible',style='Heading 2')
g.add_paragraph('Le second formulaire, observations_trajets.csv, sert à inventorier des trajets réellement mesurés ou des relevés publiés : date, mode, source et page, coordonnées des deux extrémités, distance, méthode, itinéraire et saison. Demandez aux services routiers ou aux équipes disposant de traces GPS des mesures dont la réutilisation est autorisée. Évitez de diffuser des identifiants personnels ou des traces individuelles sensibles. Une distance de catalogue sans itinéraire identifié est un benchmark; un entretien d’opinion ne la transforme pas en trajet observé. Pour tester le pourcentage de population couverte, il faudra également des observations d’accès aux mêmes services et pôles, comprenant des zones rurales et déconnectées.')
g.add_paragraph('Résultat des vérifications du 8 octobre 2026',style='Heading 2')
g.add_paragraph('Deux parcours publiés ont été comparés : Kinshasa–Matadi est proche de la référence (336 contre 355 km), mais Kinshasa–Bandundu présente un écart important (923 contre 490 km). Le second écart persiste avec les pistes. Il faut examiner les itinéraires et les jonctions avant d’interpréter les distances comme fiables. Le test n’a pas validé l’accès des ménages ni calibré une distribution d’erreurs. Les analyses provinciales et le rééchantillonnage spatial caractérisent seulement les limites de la référence satellitaire disponible.')
clean(g);g.save(O/'Guide_consultation_experts_FR.docx')
